foreach (var block in document.Blocks.OrderBy(b => b.Order))
{
    var text = block.Type switch
    {
        DocumentBlockType.Code      => ((CodeBlockContent)block.Content!).Code,
        DocumentBlockType.Paragraph => Render(((ParagraphBlockContent)block.Content!).Inlines),
        DocumentBlockType.PageBreak => "---",
        _                           => string.Empty
    };
}
